function parseGithubRepoUrl(value: string): { owner: string; repo: string } | null {
  const match = value.match(/github\.com[:/]([^/\s]+)\/([^/.\s]+)(?:\.git)?/i);
  if (!match?.[1] || !match[2]) return null;
